            GenHelpers.Invoke(ia, "HandleInteract");
            Assert.That(hands.Held, Is.EqualTo(bread), "근거: 두 번째 물건을 들 수 없음");
            Assert.That(meat.IsLoose, Is.True, "근거: 두 번째 물건을 들 수 없음");
        }

        // 바닥 물건과의 거리가 1.2m 이하(인접 유효 1.19m)이며 정면이 아닐 때 E 입력 시 줍기 성공 검증
        [Test, Requirement("FR-INT-009"), Tc("GEN-FR-INT-009-01")]
        public void ScoreTarget_Behind_Dist119_CloseRangeIgnoresAngle()
        {
            var ia = GenHelpers.Component<PlayerInteraction>("ia");
            var score = GenHelpers.Invoke(ia, "ScoreTarget", new Vector3(0, 0, -1.19f), 0, 1.2f);
            Assert.That(score, Is.GreaterThan(40), "근거: 정면이 아니어도 주울 수 있음");
        }

        // 바닥 물건과의 거리가 경계값인 1.2m이며 정면이 아닐 때 E 입력 시 줍기 성공 검증
        [Test, Requirement("FR-INT-009"), Tc("GEN-FR-INT-009-02")]
        public void ScoreTarget_Behind_Dist120_CloseRangeIgnoresAngle()
        {
            var ia = GenHelpers.Component<PlayerInteraction>("ia");
            var score = GenHelpers.Invoke(ia, "ScoreTarget", new Vector3(0, 0, -1.2f), 0, 1.2f);
            Assert.That(score, Is.GreaterThan(40), "근거: 1.2m (각도 무시)");
        }

        // 바닥 물건과의 거리가 1.2m 초과(인접 무효 1.21m)이며 정면이 아닐 때 근접 줍기(각도 무시) 미적용 검증
        [Test, Requirement("FR-INT-009"), Tc("GEN-FR-INT-009-03")]
        public void ScoreTarget_Behind_Dist121_AngleApplies()
        {
            var ia = GenHelpers.Component<PlayerInteraction>("ia");
            var score = GenHelpers.Invoke(ia, "ScoreTarget", new Vector3(0, 0, -1.21f), 0, 1.2f);
            Assert.That(score, Is.LessThan(-1000), "근거: 1.21m (각도 판정)");
        }

        // 내용물이 없는 빈 접시 제출 시 제출 거부 및 EmptyPlate 판정 검증
        [Test, Requirement("FR-PLATE-005"), Tc("GEN-FR-PLATE-005-01")]
        public void ServeTryPlace_EmptyPlate_Rejected()
        {
            var serve = GenHelpers.Component<ServeStation>("serve");
            var plate = GenHelpers.Component<PlateItem>("plate");
            var ok = serve.TryPlace(plate);
            Assert.That(ok, Is.False, "근거: 제출 거부, 판정 결과 `EmptyPlate`");
        }

        // 접시에 담긴 재료의 소유자가 접시로 변경되고 바닥 물건으로 인식되지 않는지 검증
        [Test, Requirement("FR-PLATE-009"), Tc("GEN-FR-PLATE-009-01")]
        public void TryAdd_IngredientOnPlate_IsNotLoose()
        {
            var plate = GenHelpers.Component<PlateItem>("plate");
            var d = GenHelpers.Scriptable<IngredientDefinition>();
            GenHelpers.SetMember(d, "Type", 1);
            var it = GenHelpers.Component<IngredientItem>("it");
            it.Initialize(d);
            var ok = plate.TryAdd(it);
            Assert.That(ok, Is.True, "근거: 재료의 주인이 접시가 됨. 바닥 물건으로 인식되지 않음");
            Assert.That(it.IsLoose, Is.False, "근거: 재료의 주인이 접시가 됨. 바닥 물건으로 인식되지 않음");
        }
    }
}
